-- ==========================================================================
-- B4 FOLLOW-ON FIX (qra): qra: duplicate question rewritten into a new question
--
-- Courses: qra. Rows changed: 1; rows inserted: 0.
-- Source: tools/answer-length-audit/fixes/qra.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql qra. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- qra advanced final - ord 29
  select case when md5(prompt) = 'bf5593e00dff0f8d1403871c650054f4' and md5(coalesce(explanation, '')) = '1ceebd1edfe3a05612d8dd5e2e7f6156' and md5(options::text) = md5('["0.000000006997 per year, which the source prints as 7e-9 and which follows from the printed Pd alone.", "0.000000007010 per year, which the source prints as 7e-9.", "0.000000007010 per year, which the source prints as 7.0104e-9 exactly, matching the engine to five figures.", "0.380294556093 per year, which is the whole chain''s Pd reported as though it were the contribution."]'::jsonb::text) and answer_index = 1 then 'old'
              when md5(prompt) = 'a65d7ff390362b7f610d2911c2adb890' and md5(coalesce(explanation, '')) = 'b849f9377ceb37a57596279b11316a7e' and md5(options::text) = md5('["At the release rate: only the source term belongs to the consequence course, and the dispersion, the cloud width and the Pd are QRA arithmetic worked here.", "At the effective cloud width: the steps before it are consequence modelling, and from it onward the chain is QRA arithmetic.", "At the probability of death: every step up to the printed Pd of 0.381 is QRA arithmetic this course grades, and only the contribution belongs elsewhere.", "At the contribution of 7e-9 per year: every step before it, the cloud width and the Pd included, is consequence modelling this course takes as stated."]'::jsonb::text) and answer_index = 1 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'qra' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 29 and active;
  if v_state is null then raise exception 'B4 fix qra refused: no row for qra advanced final - ord 29'; end if;
  if v_state = 'other' then raise exception 'B4 fix qra refused: qra advanced final - ord 29 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'Purple Book Appendix 6.B works one individual risk contribution at one grid point. Where does its chain pass from consequence modelling into QRA arithmetic?', options = '["At the release rate: only the source term belongs to the consequence course, and the dispersion, the cloud width and the Pd are QRA arithmetic worked here.", "At the effective cloud width: the steps before it are consequence modelling, and from it onward the chain is QRA arithmetic.", "At the probability of death: every step up to the printed Pd of 0.381 is QRA arithmetic this course grades, and only the contribution belongs elsewhere.", "At the contribution of 7e-9 per year: every step before it, the cloud width and the Pd included, is consequence modelling this course takes as stated."]'::jsonb,
           answer_index = 1, explanation = 'The early steps of Appendix 6.B are consequence modelling and belong to the consequence course; from the effective cloud width onward they are QRA arithmetic. The probability of death that comes out is an input to the contribution, which the source prints as 7e-9 per year.'
     where app_slug = 'qra' and tier = 'advanced' and scope = 'final' and module_key is not distinct from null and ord = 29 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix qra refused: qra advanced final - ord 29 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'qra' and active;
  if v_total <> 396 then raise exception 'B4 fix qra refused: qra holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix qra: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
